<?php require __DIR__ . "/vendor/autoload.php"; $app = require_once __DIR__ . "/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Http\Kernel::class); $request = Illuminate\Http\Request::create("/"); try { $response = $kernel->handle($request); echo "Status: " . $response->getStatusCode() . PHP_EOL; } catch (Throwable $e) { echo "Error: " . get_class($e) . PHP_EOL; echo "Message: " . $e->getMessage() . PHP_EOL; echo "File: " . $e->getFile() . ":" . $e->getLine() . PHP_EOL; }
